
// portal.js
(function(){if(window.staffUiReady)return;window.staffUiReady=true;
const staffParams=new URLSearchParams(location.search);
window.isStaffWorkspace=staffParams.get('staff_workspace')==='1';
if(staffParams.get('legacy_staff')==='1')localStorage.setItem('starfall-legacy-staff-view','1');
window.useLegacyStaffView=localStorage.getItem('starfall-legacy-staff-view')==='1';
if(window.isStaffWorkspace){document.body.classList.add('staff-workspace');if(!localStorage.getItem('starfall-staff-workspace-v1')){const existing=localStorage.getItem('starfall-round-v2');if(existing)localStorage.setItem('starfall-staff-workspace-v1',existing);}}
function applyStaffViewPreference(){const menu=document.getElementById('legacyStaffMenu');if(menu)menu.hidden=!window.isGameAdmin||window.isStaffWorkspace||!window.useLegacyStaffView;const toggle=document.getElementById('staffLegacyToggle');if(toggle){toggle.checked=window.useLegacyStaffView;toggle.onchange=()=>{window.useLegacyStaffView=toggle.checked;localStorage.setItem('starfall-legacy-staff-view',toggle.checked?'1':'0');};}}
function openPortalStaffWorkspace(id){const routes={control:'adminControl',alliances:'adminAlliances',multihunters:'adminMultihunters'};if(!window.isGameAdmin&&!(id==='multihunters'&&window.canMultihunt))return;const frame=document.querySelector('[data-staff-workspace="'+id+'"]');if(frame&&!frame.getAttribute('src'))frame.src='/game?staff_workspace=1&staff_tool='+id+'#'+routes[id];}
function openStaffHash(){const id=location.hash.slice(1);if(!['control','alliances','multihunters','tickets','users','news','ranks','audit'].includes(id))return;const button=document.querySelector('[data-staff-tab="'+id+'"]');if(button)button.click();}
document.addEventListener('starfall-session-ready',()=>{applyStaffViewPreference();openStaffHash();});
document.addEventListener('click',e=>{const button=e.target.closest('[data-staff-tab]');if(button){location.hash=button.dataset.staffTab;openPortalStaffWorkspace(button.dataset.staffTab);}});
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.data?.type!=='starfall-staff-height'||!Number.isFinite(e.data.height))return;for(const frame of document.querySelectorAll('[data-staff-workspace]'))if(frame.contentWindow===e.source)frame.style.height=Math.max(600,Math.min(20000,e.data.height))+'px';});
if(window.isStaffWorkspace)setInterval(()=>{if(window.parent!==window)window.parent.postMessage({type:'starfall-staff-height',height:(document.getElementById('page-admin')?.getBoundingClientRect().height||600)+40},location.origin);},1000);
applyStaffViewPreference();
if(window.isGameAdmin)openStaffHash();
})();
"use strict";
async function portalRequest(action,body){const response=await fetch('/api/portal/'+action,{credentials:'same-origin',method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw Error(data.error||'The portal is unavailable.');return data;}
(async()=>{try{const session=await portalRequest('session');window.isGameAdmin=session.user?.role==='admin';window.isPortalStaff=['admin','support','multihunter'].includes(session.user?.role);window.canMultihunt=['admin','multihunter'].includes(session.user?.role);window.canSupport=['admin','support'].includes(session.user?.role);applyPortalStaffPermissions();document.dispatchEvent(new CustomEvent('starfall-session-ready'));document.querySelectorAll('button[data-page^="admin"]').forEach(button=>button.hidden=!window.isGameAdmin);if((window.isGameAdmin||window.canMultihunt&&location.hash==='#adminMultihunters')&&['/game','/game/','/index.html'].includes(location.pathname)&&/^#admin(Alliances|Multihunters|Control|Round|Planets|Ships|State)$/.test(location.hash)&&typeof navigate==='function')navigate(location.hash.slice(1));document.querySelectorAll('[data-profile-link],[data-session-link]').forEach(el=>el.hidden=!session.user);document.querySelectorAll('[data-staff-link]').forEach(el=>el.hidden=!window.isPortalStaff);document.querySelectorAll('[data-register-link]').forEach(el=>el.hidden=!!session.user);initializePortalControls(session);const label=document.getElementById('portalUser');if(label)label.textContent=session.user?'Signed in as '+session.user.username+' · ID '+session.user.accountId:'Commander portal';const login=document.getElementById('portalLoginLink');if(login&&session.user){login.textContent='Continue game';login.href='/game';}const form=document.getElementById('loginForm');if(form){if(session.user){location.replace('/game');return;}const setup=session.setupRequired;document.getElementById('loginHeading').textContent=setup?'Create the administrator':'Welcome back';document.getElementById('loginIntro').textContent=setup?'Set up the initial admin account for this game portal.':'Sign in with your game account to enter Starfall Command.';document.getElementById('loginSubmit').textContent=setup?'Create admin account':'Sign in';if(setup){form.elements.username.value='admin';form.elements.username.readOnly=true;}form.addEventListener('submit',async event=>{event.preventDefault();const button=document.getElementById('loginSubmit'),status=document.getElementById('loginStatus');button.disabled=true;status.textContent='';try{await portalRequest(setup?'setup':'login',{username:form.elements.username.value,password:form.elements.password.value});form.elements.password.value='';location.replace('/game');}catch(error){status.textContent=error.message;button.disabled=false;}});}}catch(error){const status=document.getElementById('loginStatus');if(status)status.textContent=error.message;}})();

document.addEventListener('click',async event=>{if(event.target.closest('[data-portal-logout]')){try{await portalRequest('logout',{});location.href='/';}catch(error){alert(error.message);}}});

function applyPortalSkin(skin){if(!['Neutral','Terran','Cathaar','Xandathrii','Zikonian','Eitraides','NyanCat','AstraNexus'].includes(skin))skin='Neutral';document.body.dataset.portalSkin=skin;try{sessionStorage.setItem('starfall-portal-session-skin',skin);}catch{}const picker=document.getElementById('portalTheme');if(picker)picker.value=skin;try{if(localStorage.getItem('starfall-remember-theme')!=='false')localStorage.setItem('starfall-portal-skin',skin);else localStorage.removeItem('starfall-portal-skin');}catch{}}
{let skin='Neutral';try{skin=sessionStorage.getItem('starfall-portal-session-skin')||(localStorage.getItem('starfall-remember-theme')!=='false'?localStorage.getItem('starfall-portal-skin'):null)||skin;const rotate=sessionStorage.getItem('starfall-rotate-portal-themes')||(localStorage.getItem('starfall-remember-theme')!=='false'?localStorage.getItem('starfall-rotate-portal-themes'):null);if(rotate==='true'&&!['/game','/game/','/index.html'].includes(location.pathname)){const all=['Neutral','Terran','Cathaar','Xandathrii','Zikonian','Eitraides','NyanCat','AstraNexus'];skin=all[(all.indexOf(skin)+1)%all.length];}}catch{}applyPortalSkin(skin);}
document.addEventListener('change',event=>{if(event.target.id==='portalTheme'){sessionStorage.setItem('starfall-rotate-portal-themes','false');localStorage.removeItem('starfall-rotate-portal-themes');applyPortalSkin(event.target.value);location.hash='themes';location.reload();}if(event.target.id==='manualShipRace'){const race=event.target.value;document.querySelectorAll('[data-ship-race]').forEach(card=>card.hidden=race!=='all'&&card.dataset.shipRace!==race);}});
document.addEventListener('click',event=>{const button=event.target.closest('[data-preview-race]');if(button)applyPortalSkin(button.dataset.previewRace);});

document.addEventListener('change',event=>{if(event.target.id==='manualStatsRace')document.querySelectorAll('[data-stat-race]').forEach(table=>table.hidden=event.target.value!=='all'&&table.dataset.statRace!==event.target.value);});

async function initializePortalControls(session){document.querySelectorAll('[data-guest-auth]').forEach(el=>el.hidden=!!session.user);document.querySelectorAll('[data-member-auth]').forEach(el=>el.hidden=!session.user);const sidebarIdentity=document.getElementById('sidebarAccountIdentity');if(sidebarIdentity&&session.user)sidebarIdentity.textContent='Signed in as '+session.user.username+' · ID '+session.user.accountId;const register=document.getElementById('registerForm');if(register){if(session.user){register.hidden=true;const notice=document.createElement('p');notice.textContent='You are already signed in. Manage your existing account under User Profile.';register.after(notice);return;}register.addEventListener('submit',async e=>{e.preventDefault();const status=document.getElementById('registerStatus');if(register.elements.password.value!==register.elements.confirmPassword.value){status.textContent='Passwords do not match.';return;}const button=register.querySelector('button');button.disabled=true;try{await portalRequest('register',{username:register.elements.username.value,password:register.elements.password.value});register.reset();location.replace('/profile.html');}catch(error){status.textContent=error.message;button.disabled=false;}});}const profile=document.getElementById('profileForm');if(profile){try{const data=await portalRequest('profile');const themeSelect=document.getElementById('profileTheme');if(themeSelect&&data.allowedThemes){themeSelect.replaceChildren();for(const id of data.allowedThemes){const option=document.createElement('option');option.value=id;option.textContent=({Unimatrix999World:'Unimatrix999 Sovereign',SilverWorld:'Silver Registry',BorgWorld:'Unimatrix Sovereign',UndineWorld:'Fluidic Dominion',LegendaryWorld:'Imperial Legend',UltimateWorld:'Arrakis Ascendant'})[id]||id;themeSelect.append(option);}}document.getElementById('profileIdentity').textContent='Account: '+data.user.username+' · '+portalRankName(data.user.role)+' · Account ID: '+data.user.accountId;document.getElementById('profilePlanet').textContent=data.planet?'Planet: '+data.planet.name+' · '+data.planet.coords:'No planet yet. Continue game to confirm your colonial charter.';profile.elements.displayName.value=data.planet?.username||data.profile.display_name||data.user.username;profile.elements.theme.value=data.profile.theme;profile.addEventListener('submit',async e=>{e.preventDefault();try{await portalRequest('profile',{displayName:profile.elements.displayName.value,theme:profile.elements.theme.value});applyPortalSkin(profile.elements.theme.value);document.getElementById('profileStatus').textContent='Profile saved.';}catch(error){document.getElementById('profileStatus').textContent=error.message;}});}catch(error){document.getElementById('profileStatus').textContent=error.message;}}if(document.getElementById('staffUsers')){try{const data=await portalRequest('staff'),table=document.createElement('table');table.className='table';const head=document.createElement('tr');for(const label of ['Account','Role','Planet','Assign']){const cell=document.createElement('th');cell.textContent=label;head.append(cell);}table.append(head);for(const user of data.users){const row=document.createElement('tr'),name=document.createElement('td'),role=document.createElement('td'),owned=document.createElement('td'),action=document.createElement('td'),select=document.createElement('select'),button=document.createElement('button');name.textContent=user.username;role.textContent=user.role;owned.textContent=data.planets.filter(p=>p.ownerId===user.id).map(p=>p.name+' · '+p.coords).join(', ')||'Unassigned';for(const p of data.planets.filter(p=>!p.ownerId||p.ownerId===user.id)){const option=document.createElement('option');option.value=p.id;option.textContent=p.name+' · '+p.coords;option.selected=p.ownerId===user.id;select.append(option);}button.textContent='ASSIGN PLANET';button.className='button';button.disabled=!select.options.length;button.addEventListener('click',async()=>{try{await portalRequest('staff-assign',{userId:user.id,planetId:select.value});location.reload();}catch(error){document.getElementById('staffStatus').textContent=error.message;}});action.append(select,button);row.append(name,role,owned,action);table.append(row);}document.getElementById('staffUsers').replaceChildren(table);}catch(error){document.getElementById('staffStatus').textContent=error.message;}document.getElementById('staffResetForm')?.addEventListener('submit',async e=>{e.preventDefault();try{await portalRequest('reset',{confirmation:e.target.elements.confirmation.value});localStorage.removeItem('starfall-round-v2');localStorage.removeItem('starfall-state');localStorage.removeItem('starfall-save');document.getElementById('staffResetStatus').textContent='Round reset. Default planets regenerated.';}catch(error){document.getElementById('staffResetStatus').textContent=error.message;}});}}

const ARTICLE_ICON_PATHS={'Game mechanic update':'<path d="M32 10v44M10 32h44M16 16l32 32M16 48l32-32"/><circle cx="32" cy="32" r="12"/>','Round update':'<circle cx="32" cy="32" r="23"/><path d="M32 15v18l12 8"/>','Stats update':'<path d="M12 52V35h10v17M27 52V23h10v29M42 52V12h10v40"/>','Error update':'<path d="m32 8 26 46H6zM32 24v14m0 7v2"/>','Pauzed and resumed update':'<path d="M10 15h8v34h-8zM24 15h8v34h-8zM40 15l19 17-19 17z"/>'};
function articleIcon(category){return '<svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="3" stroke-linejoin="round" aria-hidden="true">'+(ARTICLE_ICON_PATHS[category]||ARTICLE_ICON_PATHS['Round update'])+'</svg>';}
function articleText(tag,value){const node=document.createElement(tag);node.textContent=value;return node;}
(async()=>{const form=document.getElementById('staffArticleForm');if(form){const cat=document.getElementById('articleCategory'),preview=document.getElementById('articleCategoryIcon');const refresh=()=>{preview.innerHTML=articleIcon(cat.value);preview.setAttribute('aria-label',cat.value);};refresh();cat.addEventListener('change',refresh);form.addEventListener('submit',async event=>{event.preventDefault();const button=document.getElementById('staffArticleSubmit'),status=document.getElementById('staffArticleStatus');button.disabled=true;try{const result=await portalRequest('articles',{id:form.elements.namedItem('articleId').value||undefined,title:form.elements.namedItem('title').value,synopsis:form.elements.namedItem('synopsis').value,category:form.elements.namedItem('category').value,body:form.elements.namedItem('body').value});form.reset();document.getElementById('staffArticleSubmit').textContent='PUBLISH ARTICLE';refresh();loadStaffArticles();status.replaceChildren(articleText('span','Published. '));const link=articleText('a','Open article →');link.href='/news-article.html?id='+encodeURIComponent(result.id);status.append(link);}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});}const cards=document.getElementById('staffNewsCards')||document.getElementById('portalNewsCards');if(cards){try{const data=await portalRequest('articles');for(const a of data.articles.slice(0,location.pathname==='/news.html'?100:3)){const card=document.createElement('article');card.className='card';card.dataset.newsDate=new Date(a.published_at).toISOString();card.dataset.staffArticle='true';card.dataset.newsCategory=a.category;const icon=document.createElement('span');icon.className='theme-icon';icon.innerHTML=articleIcon(a.category);const meta=articleText('span',new Date(a.published_at).toLocaleDateString()+' · '+a.category);meta.className='eyebrow';const link=articleText('a','Read news article →');link.href='/news-article.html?id='+encodeURIComponent(a.id);card.append(icon,meta,articleText('h2',a.title),articleText('p',a.synopsis),link);cards.append(card);}sortAndPinStaffNews(cards);if(cards.id!=='portalNewsCards')document.getElementById('staffPublishedNews').hidden=!data.articles.length;refreshNewsArchivePagination();}catch{cards.textContent='Staff dispatches are temporarily unavailable.';}}const view=document.getElementById('staffArticleView');if(view){try{const id=new URLSearchParams(location.search).get('id');if(!id)throw Error('Select an article from the news archive.');const data=await portalRequest('articles?id='+encodeURIComponent(id)),a=data.article,icon=document.createElement('span');icon.className='theme-icon';icon.innerHTML=articleIcon(a.category);view.dataset.newsCategory=a.category;view.classList.add('news-themed-article');view.replaceChildren(icon,articleText('span',a.category+' · '+new Date(a.published_at).toLocaleString()),articleText('h1',a.title),articleText('p',a.synopsis));for(const paragraph of a.body.split(/\n\s*\n/)){const p=document.createElement('p');p.style.whiteSpace='pre-wrap';renderArticleFormatting(p,paragraph);view.append(p);}document.title=a.title+' · Starfall Command';}catch(error){view.textContent=error.message;}}})();

function renderArticleFormatting(parent,text){const pattern=/\[(b|i|font=(?:sans-serif|serif|monospace)|size=(?:14|18|24|32))\]([\s\S]*?)\[\/(b|i|font|size)\]/g;let start=0,match;while((match=pattern.exec(text))){parent.append(document.createTextNode(text.slice(start,match.index)));const kind=match[1].split('=')[0];if(kind!==match[3]){parent.append(document.createTextNode(match[0]));}else{const el=document.createElement(kind==='b'?'strong':kind==='i'?'em':'span');if(kind==='font')el.style.fontFamily=match[1].split('=')[1];if(kind==='size')el.style.fontSize=match[1].split('=')[1]+'px';renderArticleFormatting(el,match[2]);parent.append(el);}start=pattern.lastIndex;}parent.append(document.createTextNode(text.slice(start)));}
function formatArticleSelection(tag){const editor=document.getElementById('articleBodyEditor');if(!editor)return;const from=editor.selectionStart,to=editor.selectionEnd,selected=editor.value.slice(from,to)||'Your text',close=tag.split('=')[0],wrapped='['+tag+']'+selected+'[/'+close+']';editor.setRangeText(wrapped,from,to,'select');editor.focus();}
document.addEventListener('click',e=>{const button=e.target.closest('[data-article-format]');if(button)formatArticleSelection(button.dataset.articleFormat);});document.addEventListener('change',e=>{if(e.target.matches('[data-article-font]'))formatArticleSelection('font='+e.target.value);if(e.target.matches('[data-article-size]'))formatArticleSelection('size='+e.target.value);});

async function loadStaffArticles(){const list=document.getElementById('staffArticlesList');if(!list)return;try{const data=await portalRequest('articles');list.replaceChildren();if(!data.articles.length)list.append(articleText('p','No staff articles published yet.'));for(const a of data.articles){const card=document.createElement('article');card.className='staff-article-row';card.dataset.newsCategory=a.category;const icon=document.createElement('span');icon.className='theme-icon';icon.innerHTML=articleIcon(a.category);const title=articleText('h3',a.title),meta=articleText('p',a.category+' · '+new Date(a.published_at).toLocaleString()),button=articleText('button','EDIT');button.type='button';button.className='button';button.addEventListener('click',async()=>{try{const {article}=await portalRequest('articles?id='+encodeURIComponent(a.id)),form=document.getElementById('staffArticleForm');for(const key of ['title','synopsis','category','body'])form.elements.namedItem(key).value=article[key];form.elements.namedItem('articleId').value=article.id;document.getElementById('staffArticleSubmit').textContent='SAVE CHANGES';document.getElementById('articleCategoryIcon').innerHTML=articleIcon(article.category);document.getElementById('staffArticleStatus').textContent='Editing '+article.title;form.scrollIntoView({behavior:'smooth',block:'start'});}catch(error){list.append(articleText('p',error.message));}});const copy=document.createElement('div');copy.append(title,meta);card.append(icon,copy,button);list.append(card);}}catch(error){list.textContent=error.message;}}
document.addEventListener('click',e=>{const tab=e.target.closest('[data-staff-tab]');if(tab){document.querySelectorAll('[data-staff-section]').forEach(section=>section.hidden=section.dataset.staffSection!==tab.dataset.staffTab);document.querySelectorAll('[data-staff-tab]').forEach(button=>button.classList.toggle('active',button===tab));}if(e.target.id==='staffNewArticle'){document.getElementById('staffArticleForm').reset();document.getElementById('staffArticleSubmit').textContent='PUBLISH ARTICLE';document.getElementById('staffArticleStatus').textContent='New article';}});loadStaffArticles();

function sortAndPinStaffNews(cards){const now=Date.now();for(const card of cards.children){const age=now-Date.parse(card.dataset.newsDate||''),pinned=card.dataset.staffArticle==='true'&&age>=0&&age<86400000;card.classList.toggle('staff-news-pinned',pinned);card.dataset.pinned=pinned?'true':'false';let badge=card.querySelector('.staff-pin-badge');if(pinned&&!badge){badge=articleText('span','★ PINNED · FIRST 24 HOURS');badge.className='staff-pin-badge';card.prepend(badge);}if(!pinned&&badge)badge.remove();}const items=[...cards.children];items.sort((a,b)=>(b.dataset.pinned==='true')-(a.dataset.pinned==='true')||(b.dataset.newsDate||'').localeCompare(a.dataset.newsDate||''));for(const card of items)cards.append(card);}
setInterval(()=>document.querySelectorAll('#portalNewsCards,#staffNewsCards').forEach(sortAndPinStaffNews),60000);

async function refreshPortalUniverse(){if(!document.getElementById('portalPlanetCount'))return;try{const data=await portalRequest('worldstats');document.getElementById('portalPlanetCount').textContent=Number(data.planets).toLocaleString();document.getElementById('portalAsteroidCount').textContent=Number(data.asteroids).toLocaleString();document.getElementById('portalAllianceCount').textContent=Number(data.alliances).toLocaleString();document.getElementById('portalUniverseStatus').textContent='SHARED UNIVERSE · LIVE DATABASE';}catch(error){document.getElementById('portalUniverseStatus').textContent='Universe status temporarily unavailable.';}}refreshPortalUniverse();setInterval(refreshPortalUniverse,30000);

document.addEventListener('click',e=>{const link=e.target.closest('[data-footer-placeholder]');if(link){e.preventDefault();document.getElementById('portalFooterStatus').textContent=link.dataset.footerPlaceholder+' — coming soon.';}});
// Reuse this hover/focus/tap reveal pattern for future hidden content.
document.querySelectorAll('.race-reference-card').forEach(card=>{const button=card.querySelector('.race-expand');if(!button)return;const close=()=>{card.classList.remove('is-expanded');button.setAttribute('aria-expanded','false');};button.addEventListener('click',()=>{const open=true;document.querySelectorAll('.race-reference-card.is-expanded').forEach(other=>{other.classList.remove('is-expanded');other.querySelector('.race-expand').setAttribute('aria-expanded','false');});card.classList.toggle('is-expanded',open);button.setAttribute('aria-expanded',String(open));});button.addEventListener('mouseenter',()=>{card.classList.add('is-expanded');button.setAttribute('aria-expanded','true');});let closeTimer;card.addEventListener('mouseenter',()=>clearTimeout(closeTimer));card.addEventListener('mouseleave',()=>{closeTimer=setTimeout(close,200);});card.addEventListener('focusout',e=>{if(!card.contains(e.relatedTarget))close();});card.addEventListener('keydown',e=>{if(e.key==='Escape'){close();button.focus();}});});
(async()=>{const link=document.querySelector('[data-intel-dump]');if(!link)return;try{const response=await fetch('/api/alliance-intel',{credentials:'same-origin'});link.hidden=!response.ok;}catch{link.hidden=true;}})();
// Hidden discoveries share one hover, focus and touch pattern.
document.querySelectorAll('.secret-reveal').forEach(box=>{box.addEventListener('click',e=>{if(e.target===box||e.target.classList.contains('secret-marker'))box.classList.toggle('is-revealed');});box.addEventListener('mouseleave',()=>box.classList.remove('is-revealed'));box.addEventListener('keydown',e=>{if(e.key==='Escape')box.classList.remove('is-revealed');});});
document.querySelectorAll('[data-secret-trek]').forEach(control=>{try{const saved=JSON.parse(localStorage.getItem('starfall-round-v2')||'{}');control.checked=!!saved.userSettings?.trekFleetEnabled;}catch{}control.addEventListener('change',()=>{try{const saved=JSON.parse(localStorage.getItem('starfall-round-v2')||'{}');saved.userSettings={...saved.userSettings,trekFleetEnabled:control.checked};localStorage.setItem('starfall-round-v2',JSON.stringify(saved));}catch{}});});

const rememberTheme=document.getElementById('rememberPortalTheme');if(rememberTheme){rememberTheme.checked=localStorage.getItem('starfall-remember-theme')!=='false';rememberTheme.addEventListener('change',()=>{localStorage.setItem('starfall-remember-theme',String(rememberTheme.checked));if(rememberTheme.checked)localStorage.setItem('starfall-portal-skin',document.body.dataset.portalSkin||'Neutral');else localStorage.removeItem('starfall-portal-skin');});}document.addEventListener('click',e=>{const tab=e.target.closest('[data-profile-tab]');if(tab){document.querySelectorAll('[data-profile-panel]').forEach(panel=>panel.hidden=panel.dataset.profilePanel!==tab.dataset.profileTab);document.querySelectorAll('[data-profile-tab]').forEach(button=>button.classList.toggle('active',button===tab));location.hash=tab.dataset.profileTab;}});

if(location.hash==='#themes'){document.querySelectorAll('[data-profile-panel]').forEach(panel=>panel.hidden=panel.dataset.profilePanel!=='themes');document.querySelectorAll('[data-profile-tab]').forEach(button=>button.classList.toggle('active',button.dataset.profileTab==='themes'));}

if(location.hash==='#tickets'){document.querySelectorAll('[data-profile-panel]').forEach(panel=>panel.hidden=panel.dataset.profilePanel!=='tickets');document.querySelectorAll('[data-profile-tab]').forEach(button=>button.classList.toggle('active',button.dataset.profileTab==='tickets'));}

const rotatePortal=document.getElementById('rotatePortalThemes');if(rotatePortal){rotatePortal.checked=(sessionStorage.getItem('starfall-rotate-portal-themes')||(localStorage.getItem('starfall-remember-theme')!=='false'?localStorage.getItem('starfall-rotate-portal-themes'):null))==='true';rotatePortal.addEventListener('change',()=>{sessionStorage.setItem('starfall-rotate-portal-themes',String(rotatePortal.checked));if(localStorage.getItem('starfall-remember-theme')!=='false')localStorage.setItem('starfall-rotate-portal-themes',String(rotatePortal.checked));else localStorage.removeItem('starfall-rotate-portal-themes');location.hash='themes';location.reload();});}if(rememberTheme)rememberTheme.addEventListener('change',()=>{if(rememberTheme.checked)localStorage.setItem('starfall-rotate-portal-themes',sessionStorage.getItem('starfall-rotate-portal-themes')||'false');else localStorage.removeItem('starfall-rotate-portal-themes');});
async function portalAllianceRequest(body){return portalRequest('alliance-manager',body);}
async function loadPortalAllianceManager(){const root=document.getElementById('portalAllianceManager');if(!root)return;try{const data=await portalAllianceRequest(),directory=await portalRequestDirectoryRevision();const fields=(a,prefix)=>'<div class="profile-alliance-fields">'+[['name','Alliance name'],['tag','Tag'],['description','Description'],['recruitmentMessage','Recruitment message'],['motd','MOTD']].map(([key,label])=>'<label>'+label+(key==='name'||key==='tag'?'<input id="'+prefix+'-'+key+'" value="'+portalEscape(a[key]||'')+'" maxlength="'+(key==='name'?40:8)+'">':'<textarea id="'+prefix+'-'+key+'" maxlength="2000" rows="3">'+portalEscape(a[key]||'')+'</textarea>')+'</label>').join('')+'</div>';const card=(a,active=false)=>{const id=active?'active':a.id,canEdit=active?a.canEdit:a.status!=='Active'&&a.canEdit,status=active?'Active':a.status;return '<article class="profile-theme-box portal-alliance-card" data-manager-id="'+portalEscape(a.id||'')+'" data-manager-prefix="'+id+'" data-manager-revision="'+directory+'"><div class="section-bar"><b>'+portalEscape(a.name)+'</b><span>'+status+'</span></div><p>'+(active?'Current round alliance · rank '+portalEscape(a.rank):'Registered alliance and your personal key')+'</p>'+(canEdit?fields(a,id)+'<button class="button" data-alliance-manager-action="update">SAVE ALLIANCE SETTINGS</button>':'<p>Only an Owner can edit alliance settings.</p>')+(!active&&status!=='Revoked'?'<div class="portal-key-controls"><button class="button secondary" data-alliance-manager-action="key">SHOW MY KEY</button><input readonly type="text" data-manager-secret placeholder="Personal key hidden"><label>My disclosure passphrase<input type="password" data-manager-phrase autocomplete="new-password" minlength="12" maxlength="128"></label><button class="button secondary" data-alliance-manager-action="phrase">SET MY PASSPHRASE</button><button class="button secondary" data-alliance-manager-action="rotate">ROTATE MY KEY</button>'+(status==='Reserved'||status==='Archived'?'<button class="button" data-alliance-manager-action="activate">ACTIVATE IN CURRENT ROUND</button>':'')+'</div>':'')+((active&&a.canEdit)||a.status!=='Active'&&a.canAddHolders?'<div class="portal-holder-controls"><h3>Add a keyholder</h3><p>Up to two additional holders. For an active alliance the account must already be a member and becomes an Owner. Each holder sees only their personal key.</p><label>Account username<input data-manager-holder autocomplete="off" maxlength="32"></label><button class="button secondary" data-alliance-manager-action="addHolder">ADD KEYHOLDER</button></div>':'')+'</article>';};root.innerHTML='<section class="profile-theme-box"><div class="section-bar"><b>INACTIVE ALLIANCE RESERVATIONS</b><span>'+data.reservedCount+' / '+data.limit+'</span></div><p>Reserving an alliance does not join it or change your active round alliance.</p>'+fields({},'reserve')+'<label>Optional disclosure passphrase<input id="reserve-phrase" type="password" minlength="12" maxlength="128" autocomplete="new-password"></label><button class="button" data-alliance-manager-reserve '+(data.reservedCount>=data.limit?'disabled':'')+'>RESERVE ALLIANCE & GENERATE MY KEY</button></section>'+(data.active?'<h3>Current active alliance</h3>'+card(data.active,true):'<p>You currently have no active alliance.</p>')+'<h3>My registered alliances & keys</h3>'+data.alliances.map(a=>card(a)).join('')+'<p id="portalAllianceManagerStatus" class="status" role="status"></p>';}catch(error){root.textContent=error.message;}}
function portalEscape(text){return String(text??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
async function portalRequestDirectoryRevision(){const response=await fetch('/api/planets',{credentials:'same-origin'}),data=await response.json();if(!response.ok)throw Error(data.error||'Cannot load current round.');return data.revision;}
function managerFields(prefix){return Object.fromEntries(['name','tag','description','recruitmentMessage','motd'].map(k=>[k,document.getElementById(prefix+'-'+k)?.value||'']));}
document.addEventListener('click',async e=>{const tab=e.target.closest('[data-profile-tab="alliances"]');if(tab)loadPortalAllianceManager();const reserve=e.target.closest('[data-alliance-manager-reserve]'),button=e.target.closest('[data-alliance-manager-action]');if(!reserve&&!button)return;const status=document.getElementById('portalAllianceManagerStatus');try{if(reserve){reserve.disabled=true;await portalAllianceRequest({action:'reserve',...managerFields('reserve'),passphrase:document.getElementById('reserve-phrase').value||undefined});await loadPortalAllianceManager();document.getElementById('portalAllianceManagerStatus').textContent='Alliance reserved and your personal encrypted key generated.';return;}const card=button.closest('[data-manager-id]'),action=button.dataset.allianceManagerAction,body={action,id:card.dataset.managerId,revision:Number(card.dataset.managerRevision)};if(action==='update')Object.assign(body,managerFields(card.dataset.managerPrefix));if(action==='addHolder')body.username=card.querySelector('[data-manager-holder]').value;if(['phrase','rotate'].includes(action))body.passphrase=card.querySelector('[data-manager-phrase]').value;if(action==='rotate'&&!confirm('Rotate your personal key? Its old key and disclosure passphrase will stop working.'))return;if(action==='activate'&&!confirm('Activate this alliance in the current round and leave your current alliance?'))return;button.disabled=true;const result=await portalAllianceRequest(body);if(action==='key'){const field=card.querySelector('[data-manager-secret]');field.value=result.secret;setTimeout(()=>{field.value='';},60000);button.disabled=false;return;}await loadPortalAllianceManager();document.getElementById('portalAllianceManagerStatus').textContent=action==='activate'?'Alliance activated. You are its Owner.':'Alliance manager updated.';}catch(error){if(status)status.textContent=error.message;if(reserve)reserve.disabled=false;if(button)button.disabled=false;}});
if(location.hash==='#alliances'&&document.getElementById('portalAllianceManager')){document.querySelectorAll('[data-profile-panel]').forEach(panel=>panel.hidden=panel.dataset.profilePanel!=='alliances');loadPortalAllianceManager();}
function portalRankName(role){return {player:'Player',support:'Support',multihunter:'Multihunter',admin:'Administrator'}[role]||role;}
function applyPortalStaffPermissions(){for(const button of document.querySelectorAll('[data-staff-tab]')){const id=button.dataset.staffTab;button.hidden=id==='round'?false:id==='audit'?!window.isPortalStaff:id==='tickets'?!window.canSupport:id==='multihunters'?!window.canMultihunt:id==='control'?!window.isGameAdmin:!window.isGameAdmin;}const legacy=document.getElementById('staffLegacyToggle');if(legacy&&!window.isGameAdmin)legacy.closest('.profile-theme-box').hidden=true;}
async function loadPortalAccountRanks(){const root=document.getElementById('portalAccountRanks');if(!root||!window.isGameAdmin)return;try{const response=await fetch('/api/admin/account-ranks',{credentials:'same-origin'}),data=await response.json();if(!response.ok)throw Error(data.error||'Ranks unavailable.');root.innerHTML='<div class="profile-alliance-fields">'+data.ranks.map(r=>'<article class="profile-theme-box"><h3>'+portalEscape(r.name)+'</h3><p>'+portalEscape(r.permissions)+'</p></article>').join('')+'</div><div class="table-wrap"><table class="table"><thead><tr><th>Account</th><th>Current rank</th><th>Assign rank</th><th>Save</th></tr></thead><tbody>'+data.users.map(user=>'<tr><td>'+portalEscape(user.username)+'</td><td>'+portalEscape(portalRankName(user.role))+'</td><td><select id="portal-rank-'+portalEscape(user.id)+'">'+data.ranks.map(r=>'<option value="'+r.id+'" '+(r.id===user.role?'selected':'')+'>'+r.name+'</option>').join('')+'</select></td><td><button class="button secondary" data-save-portal-rank="'+portalEscape(user.id)+'">SAVE RANK</button></td></tr>').join('')+'</tbody></table></div><p id="portalRankStatus" role="status"></p>';}catch(error){root.textContent=error.message;}}
document.addEventListener('click',async e=>{if(e.target.closest('[data-staff-tab="ranks"]'))loadPortalAccountRanks();const button=e.target.closest('[data-save-portal-rank]');if(button&&window.isGameAdmin){try{button.disabled=true;const response=await fetch('/api/admin/account-ranks',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:button.dataset.savePortalRank,rank:document.getElementById('portal-rank-'+button.dataset.savePortalRank).value})}),data=await response.json();if(!response.ok)throw Error(data.error||'Rank update failed.');await loadPortalAccountRanks();document.getElementById('portalRankStatus').textContent='Account rank saved. Permissions apply on the next request.';}catch(error){button.disabled=false;document.getElementById('portalRankStatus').textContent=error.message;}}});
let staffAuditOffset=0;
async function loadStaffPlanetAudit(){const root=document.getElementById('staffPlanetAudit');if(!root||!window.isPortalStaff)return;try{const actor=document.getElementById('auditActor')?.value||'',planet=document.getElementById('auditPlanet')?.value||'',query=new URLSearchParams({actor,planet,offset:String(staffAuditOffset)}),response=await fetch('/api/admin/planet-audit?'+query,{credentials:'same-origin'}),data=await response.json();if(!response.ok)throw Error(data.error||'Audit unavailable.');root.innerHTML='<form id="staffAuditFilters" class="profile-alliance-fields"><label>Staff account<input id="auditActor" value="'+portalEscape(actor)+'" placeholder="Filter by staff username"></label><label>Planet or coordinates<input id="auditPlanet" value="'+portalEscape(planet)+'" placeholder="Filter by planet or coordinates"></label><button class="button" type="submit">FILTER EDITS</button></form><div class="staff-audit-cards">'+data.records.map(record=>'<article class="profile-theme-box staff-audit-card"><div class="section-bar"><b>'+portalEscape(record.planet_name)+' · '+portalEscape(record.coords)+'</b><span>'+new Date(record.created_at).toLocaleString()+'</span></div><p><b>'+portalEscape(record.actor_name)+'</b> · '+portalEscape(record.action)+' · '+record.changes.fields.length+' changes</p><details><summary>VIEW CHANGED FIELDS</summary><div class="table-wrap"><table class="table"><thead><tr><th>Field</th><th>Previous value</th><th>New value</th></tr></thead><tbody>'+record.changes.fields.map(change=>'<tr><td>'+portalEscape(change.field)+'</td><td>'+portalEscape(change.old)+'</td><td>'+portalEscape(change.new)+'</td></tr>').join('')+'</tbody></table></div>'+(record.changes.truncated?'<p>First 300 fields shown for this large edit.</p>':'')+'</details></article>').join('')+(data.records.length?'':'<p>No staff planet edits match these filters.</p>')+'</div><div class="actions">'+(staffAuditOffset?'<button class="button secondary" data-staff-audit-offset="'+Math.max(0,staffAuditOffset-25)+'">NEWER</button>':'')+(data.hasMore?'<button class="button secondary" data-staff-audit-offset="'+data.nextOffset+'">OLDER</button>':'')+'</div>';}catch(error){root.textContent=error.message;}}
document.addEventListener('click',e=>{if(e.target.closest('[data-staff-tab="audit"]'))loadStaffPlanetAudit();const page=e.target.closest('[data-staff-audit-offset]');if(page){staffAuditOffset=Number(page.dataset.staffAuditOffset);loadStaffPlanetAudit();}});
document.addEventListener('submit',e=>{if(e.target.id==='staffAuditFilters'){e.preventDefault();staffAuditOffset=0;loadStaffPlanetAudit();}});

(()=>{const search=document.getElementById('manualSearch'),home=document.getElementById('manual-home');if(!search||!home)return;const chapters=[...document.querySelectorAll('.manual-chapter')],links=[...document.querySelectorAll('[data-manual-link]')],results=document.getElementById('manualSearchResults'),status=document.getElementById('manualSearchStatus');function showChapter(){const hash=decodeURIComponent(location.hash.slice(1)),target=document.getElementById(hash),chapter=target?.closest('.manual-chapter'),query=search.value.trim().toLowerCase();if(query){const words=query.split(/\s+/),found=chapters.filter(c=>words.every(w=>c.textContent.toLowerCase().includes(w)));home.hidden=true;chapters.forEach(c=>c.hidden=true);results.hidden=false;results.replaceChildren();const heading=document.createElement('h2');heading.textContent=found.length+' matching chapters';results.append(heading);if(!found.length){const text=document.createElement('p');text.textContent='No matching chapters. Try fewer words or another spelling.';results.append(text);}for(const c of found){const card=document.createElement('article');card.className='manual-search-hit';const link=document.createElement('a');link.href='#'+c.id;link.textContent=c.dataset.chapterTitle;link.addEventListener('click',()=>{search.value='';showChapter();});const excerpt=document.createElement('p');excerpt.textContent=c.querySelector('.manual-subsection')?.textContent.trim().slice(0,220)||'';card.append(link,excerpt);results.append(card);}status.textContent=found.length+' of '+chapters.length+' chapters';links.forEach(l=>l.hidden=!found.some(c=>c.id===l.dataset.manualLink));}else{results.hidden=true;home.hidden=!!chapter;chapters.forEach(c=>c.hidden=c!==chapter);links.forEach(l=>{l.hidden=false;if(l.dataset.manualLink===chapter?.id)l.setAttribute('aria-current','page');else l.removeAttribute('aria-current');});status.textContent=chapter?chapter.dataset.chapterTitle:chapters.length+' chapters · choose a topic';}document.querySelectorAll('.manual-nav-group').forEach(g=>g.hidden=![...g.querySelectorAll('a')].some(l=>!l.hidden));}search.addEventListener('input',showChapter);document.getElementById('manualClearSearch').addEventListener('click',()=>{search.value='';showChapter();search.focus();});document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&document.getElementById(a.getAttribute('href').slice(1))){search.value='';showChapter();}});window.addEventListener('hashchange',()=>{showChapter();const target=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(target&&!target.hidden)target.scrollIntoView({block:'start'});});showChapter();})();

function refreshNewsArchivePagination(){const archive=document.querySelector('.news-archive');if(!archive)return;const staff=document.getElementById('staffNewsCards'),articles=[...(staff?.querySelectorAll(':scope > article')||[]),...archive.querySelectorAll(':scope > article')].sort((a,b)=>{const date=e=>Date.parse(e.dataset.newsDate||e.querySelector('time')?.dateTime||'')||0;return date(b)-date(a);});const pages=Math.max(1,Math.ceil(articles.length/20));let page=Math.max(1,Math.min(pages,Number(new URLSearchParams(location.search).get('page'))||1));page=Math.trunc(page);articles.forEach((a,i)=>a.hidden=i<(page-1)*20||i>=page*20);const staffSection=document.getElementById('staffPublishedNews');if(staffSection)staffSection.hidden=![...(staff?.children||[])].some(a=>!a.hidden);let pagers=[...document.querySelectorAll('.news-pagination')];if(!pagers.length){for(const position of ['before','after']){const nav=document.createElement('nav');nav.className='news-pagination';nav.setAttribute('aria-label','News archive pagination');position==='before'?archive.before(nav):archive.after(nav);}pagers=[...document.querySelectorAll('.news-pagination')];}for(const nav of pagers){nav.replaceChildren();const status=document.createElement('span');status.className='news-page-status';status.textContent=articles.length?((page-1)*20+1)+'–'+Math.min(page*20,articles.length)+' of '+articles.length+' articles · Page '+page+' of '+pages:'No articles';nav.append(status);const button=(label,target,disabled,current=false)=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.disabled=disabled;if(current)b.setAttribute('aria-current','page');b.addEventListener('click',()=>{const url=new URL(location.href);url.searchParams.set('page',target);history.replaceState(null,'',url);refreshNewsArchivePagination();document.querySelector('.news-pagination').scrollIntoView({block:'start'});});nav.append(b);};button('← Previous',page-1,page===1);for(let n=1;n<=pages;n++)if(n===1||n===pages||Math.abs(n-page)<=2)button(String(n),n,false,n===page);button('Next →',page+1,page===pages);}}
refreshNewsArchivePagination();window.addEventListener('popstate',refreshNewsArchivePagination);


// ambient.js
(()=>{'use strict';const game=['/game','/game/','/index.html'].includes(location.pathname),audio=new Audio('/assets/media/vesper-desert-score.mp3?v=0.97.0');audio.hidden=true;audio.preload='none';document.body.append(audio);audio.loop=true;audio.volume=.22;let enabled=false,toolbar,videoPlaying=false;try{if(!game)enabled=localStorage.getItem('starfall-portal-music-enabled')==='true';}catch{}
function wanted(){return game?typeof state!=='undefined'&&!!state.userSettings.gameAmbientMusic:enabled;}
function status(message){const el=document.getElementById(game?'gameMusicStatus':'portalMusicStatus');if(el)el.textContent=message;const button=document.getElementById('portalMusicToggle');if(button){button.textContent=wanted()?'MUTE MUSIC':'ENABLE MUSIC';button.setAttribute('aria-pressed',String(wanted()));}}
async function apply(){if(!wanted()||videoPlaying){audio.pause();status(!wanted()?'Music off':'Music paused while video plays');return;}try{await audio.play();status('Vesper desert score · playing');}catch{status('Music ready · starts after your next click');}}
window.applyAmbientMusic=apply;
if(!game){toolbar=document.createElement('div');toolbar.className='portal-music-toolbar';toolbar.innerHTML='<span id="portalMusicStatus" role="status">Original cinematic ambience</span><button id="portalMusicToggle" class="button secondary" type="button">MUTE MUSIC</button><label for="portalMusicVolume">Volume <input id="portalMusicVolume" type="range" min="0" max="100" value="22"></label>';const settings=document.querySelector('.profile-theme-section');if(settings){toolbar.classList.add('profile-theme-box');settings.append(toolbar);}else{toolbar.hidden=true;document.body.append(toolbar);}document.getElementById('portalMusicToggle').addEventListener('click',()=>{enabled=!enabled;try{localStorage.setItem('starfall-portal-music-enabled',String(enabled));}catch{}apply();});document.getElementById('portalMusicVolume').addEventListener('input',e=>audio.volume=Number(e.target.value)/100);}
document.addEventListener('pointerdown',()=>{if(wanted()&&audio.paused&&!videoPlaying)apply();});document.addEventListener('keydown',()=>{if(wanted()&&audio.paused&&!videoPlaying)apply();});document.addEventListener('play',e=>{if(e.target.tagName==='VIDEO'){videoPlaying=true;apply();}},true);for(const event of ['pause','ended'])document.addEventListener(event,e=>{if(e.target.tagName==='VIDEO'){videoPlaying=[...document.querySelectorAll('video')].some(v=>!v.paused&&!v.ended);apply();}},true);document.addEventListener('visibilitychange',()=>{if(document.hidden)audio.pause();else apply();});apply();})();


