const demoRounds=[{generation:0,name:'The First Beacon',winner:'Admiral Lyra',winningPlanet:'Dawnspire',winningScore:18420500,alliance:'Vesper Accord',allianceScore:94000600,players:184,galaxies:19,population:384600,ticks:672,endedAt:Date.UTC(2026,7,1),demo:true},{generation:1,name:'Echoes of the Gate',winner:'Marshal Orion',winningPlanet:'Silver Meridian',winningScore:22180600,alliance:'Aurora Pact',allianceScore:118450300,players:246,galaxies:25,population:561750,ticks:672,endedAt:Date.UTC(2026,8,1),demo:true},{generation:2,name:'The Emerald Frontier',winner:'Commander Selene',winningPlanet:'Verdant Crown',winningScore:25810900,alliance:'Horizon Union',allianceScore:143200800,players:312,galaxies:32,population:728400,ticks:672,endedAt:Date.UTC(2026,9,1),demo:true}];
const historyEsc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const historyNumber=n=>Number(n||0).toLocaleString('en-US');
async function renderRoundHistory(){const root=document.getElementById('roundArchive');try{const response=await fetch('/api/round-history'),data=await response.json();if(!response.ok)throw Error('Archive unavailable.');const settings=await fetch('/api/site-management').then(r=>r.json());const demo=data.rounds.length===0&&settings.roundHistoryDemo!==false,rounds=demo?demoRounds:data.rounds;if(!rounds.length){root.innerHTML='<h2>No completed rounds archived</h2><p>Demonstration examples are disabled in Site management.</p>';return;}root.innerHTML=(demo?'<aside class="history-demo"><b>DEMONSTRATION ARCHIVE</b><p>These rounds, names and statistics are fictional layout examples. They disappear automatically as soon as the first real completed round is archived.</p></aside>':'')+'<div class="history-kpis"><article><small>'+ (demo?'DEMO ROUNDS':'ARCHIVED ROUNDS')+'</small><b>'+rounds.length+'</b></article><article><small>TOTAL PARTICIPATIONS</small><b>'+historyNumber(rounds.reduce((n,r)=>n+r.players,0))+'</b></article><article><small>HIGHEST RECORDED SCORE</small><b>'+historyNumber(Math.max(...rounds.map(r=>r.winningScore)))+'</b></article></div><div class="round-history-grid">'+[...rounds].reverse().map(r=>'<article class="round-history-card"><header><span class="eyebrow">'+(r.demo?'FICTIONAL DEMO':'OFFICIAL ARCHIVE')+' · ROUND '+String(r.generation+1).padStart(2,'0')+'</span><h2>'+historyEsc(r.name)+'</h2><p>Ended '+new Date(r.endedAt).toLocaleDateString()+' · '+r.ticks+' ticks</p></header><div class="history-champion"><span aria-hidden="true">✦</span><div><small>ROUND CHAMPION</small><h3>'+historyEsc(r.winner)+'</h3><p>'+historyEsc(r.winningPlanet)+' · '+historyNumber(r.winningScore)+' score</p></div></div><dl><div><dt>Leading alliance</dt><dd>'+historyEsc(r.alliance)+'</dd></div><div><dt>Alliance score</dt><dd>'+historyNumber(r.allianceScore)+'</dd></div><div><dt>Participating commanders</dt><dd>'+historyNumber(r.players)+'</dd></div><div><dt>Galaxies</dt><dd>'+r.galaxies+'</dd></div><div><dt>Final population</dt><dd>'+historyNumber(r.population)+'</dd></div></dl><footer>'+ (r.demo?'Example data · no gameplay rewards or standings':'Recorded from the completed round before its reset')+'</footer></article>').join('')+'</div>';}catch(e){root.textContent=e.message;}}
renderRoundHistory();

